<script setup lang="ts">
import {computed,ref,watch,onUnmounted} from 'vue';import {useApplication} from '../../application';import type {ExportFormat} from '../../shared/api/minutes-exports';
const props=defineProps<{sourceRevision:string;review:boolean;dirty:boolean}>(),app=useApplication(),exports=app.minutesExportCommands,dialog=ref<HTMLDialogElement>(),opened=ref(false),format=ref<ExportFormat>('md'),message=ref('');
const labels:Record<string,string>={READY:'正在排队',RUNNING:'正在生成文件',RECONCILING:'正在确认结果',SUCCEEDED:'导出已完成',FAILED:'导出失败，可以重新导出',CANCELLED:'导出已取消',STALE:'保存版本已变化，请重新导出'};
const unknown=computed(()=>!!exports.command.snapshot.value&&!exports.job.value),sameSource=computed(()=>!exports.job.value||exports.job.value.sourceRevision===props.sourceRevision);
let timer:ReturnType<typeof setTimeout>|null=null;
function schedule(){if(timer!==null)clearTimeout(timer);timer=null;if(!opened.value||!exports.available.value||!exports.job.value||!['READY','RUNNING','RECONCILING'].includes(exports.job.value.state))return;timer=setTimeout(async()=>{try{await exports.poll();}catch{/* The durable task remains available for an explicit retry. */}finally{schedule();}},exports.error.value?5000:1500);}
watch(()=>[exports.job.value,exports.available.value,opened.value],schedule);
watch(()=>props.review,review=>{if(!review)format.value='md';});
async function run(action:()=>Promise<unknown>){message.value='';try{await action();}catch(cause){message.value=cause instanceof Error?cause.message:'导出暂不可用，请重试。';}}
function show(){opened.value=true;dialog.value?.showModal();if(exports.job.value)void run(()=>exports.poll());}
function close(){opened.value=false;dialog.value?.close();}
onUnmounted(()=>{if(timer!==null)clearTimeout(timer);});
</script>
<template><button class="btn sm" :disabled="dirty||!exports.available.value" :title="dirty?'请先保存修改':'导出当前已保存版本'" @click="show">⇩ {{review?'导出':'下载'}}</button><dialog ref="dialog" class="export-dialog" aria-labelledby="minutes-export-title" @cancel="opened=false"><header class="between"><h3 id="minutes-export-title">导出会议纪要</h3><button class="btn sm" @click="close">关闭</button></header><p class="small muted">{{review?'从当前可查看的已保存版本生成文件。':'保存修改后，可下载当前版本的 Markdown 文件。'}}</p><label class="format">文件格式<select v-model="format" :disabled="exports.busy.value||exports.pending.value"><option value="md">Markdown（.md）</option><option v-if="review" value="pdf">PDF（.pdf）</option><option v-if="review" value="docx">Word（.docx）</option></select></label><p v-if="dirty" role="status">请先保存正文修改。</p><p v-if="unknown" role="status">有一个导出请求等待确认，请先查回原导出结果。</p><p v-if="exports.job.value" role="status">{{labels[exports.job.value.state]}}</p><p v-if="!sameSource||exports.job.value?.state==='SUCCEEDED'&&!exports.job.value.fileId" class="small">保存版本或可访问状态已变化，请重新读取会议后导出。</p><p v-if="message||exports.error.value||app.minutesExportScopeError.value" role="alert">{{message||exports.error.value||app.minutesExportScopeError.value}}</p><footer><button v-if="unknown&&['PREPARED','UNCERTAIN','ACKNOWLEDGED'].includes(exports.command.state.value)" class="btn primary" :disabled="exports.busy.value||!exports.available.value" @click="run(()=>exports.recover())">查回原导出</button><button v-if="['CONFLICT','REJECTED'].includes(exports.command.state.value)" class="btn" @click="run(async()=>exports.discardRejected())">重新选择版本</button><button v-if="exports.job.value" class="btn" :disabled="exports.busy.value||!exports.available.value" @click="run(()=>exports.poll())">刷新进度</button><a v-if="exports.download.value&&sameSource" class="btn primary" :href="exports.download.value" download>下载文件</a><button v-if="!exports.pending.value" class="btn" :disabled="dirty||exports.busy.value||!exports.available.value" @click="run(()=>exports.start(sourceRevision,format))">{{exports.job.value?'再次导出':'生成文件'}}</button></footer></dialog></template>
<style scoped>.export-dialog{margin:auto;width:min(520px,calc(100vw - 40px));padding:24px;border:1px solid var(--border);border-radius:10px;color:var(--text)}.export-dialog::backdrop{background:#11184966}.export-dialog p{margin-top:16px}.format{display:flex;align-items:center;gap:16px;margin-top:20px}.format select{flex:1;padding:8px;border:1px solid var(--border);border-radius:5px;font:inherit}.export-dialog footer{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px;margin-top:24px}.export-dialog a{text-decoration:none}</style>
